entries[45038] = { ["name"] = "Fragment von Val'anyr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (30)\nKlassen: Paladin , Priester , Schamane , Druide\nBenötigt Stufe 80\nBenutzen: Kombiniert 30 Fragmente von Val'anyr und formt so die Zerschmetterten Fragmente von Val'anyr.\n\"Die Fragmente dieses Hammers glühen in einem kühlen, beruhigenden Licht.\"" }
entries[45039] = { ["name"] = "Zerschmetterte Fragmente von Val'anyr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nKlassen: Paladin , Priester , Schamane , Druide\n\"Die Fragmente dieses Hammers glühen in einem kühlen, beruhigenden Licht.\"" }
entries[45041] = { ["name"] = "Kunsttest", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand Streitkolben\n86 - 271 Schaden Tempo 1.80\n(99.17 Schaden pro Sekunde)\n+93 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nErhöht die Angriffskraft um 617 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Zaubermacht um 520.\nAnlegen: Stellt alle 5 Sek. 19 Mana wieder her." }
