entries[45046] = { ["name"] = "Holzfällerbeil", ["text"] = "Questgegenstand\nBenutzen: Fällt eine stehende Kristallsangeiche und schlägt daraus grob gehauenes Bauholz. (4 Sek. Abklingzeit)" }
