entries[45050] = { ["name"] = "Formel: Rauchendes Herz des Berges", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (265)\nBenutzen: Lehrt Euch die Herstellung eines rauchenden Herzens des Berges.\nRauchendes Herz des Berges\nWird beim Aufheben gebunden\nEinzigartig\nSchmuck\n150 Rüstung\nBenötigt Stufe 50\nAnlegen: Erhöht die kritische Trefferwertung um 17.\nBenötigt Essenz des Feuers (3), Kleiner glänzender Splitter (3)" }
entries[45052] = { ["name"] = "Gruffs Schuppengamaschen", ["text"] = "Wird beim Anlegen gebunden\nBeine Leder\n126 Rüstung\n+16 Beweglichkeit\nHaltbarkeit 65 / 65\nBenötigt Stufe 48\nAnlegen: Erhöht die Angriffskraft um 32." }
entries[45054] = { ["name"] = "Prismatischer schwarzer Diamant", ["text"] = "\"Die Qualitäten dieses Edelsteins sind unbekannt, bis er geschliffen wird.\"" }
entries[45056] = { ["name"] = "Rolle der Stabverzauberung - Große Zaubermacht", ["text"] = "Benutzen: Einen Stab dauerhaft verzaubern, sodass die Zaubermacht um 81 erhöht wird. Erfordert einen Gegenstand der Stufe 60 oder höher." }
entries[45057] = { ["name"] = "Aufziehbarer Zugzerstörer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Mit Rechtsklick einen aufziehbaren Zugzerstörer aufstellen. (30 Min Abklingzeit)" }
