entries[45061] = { ["name"] = "Schaumstoffschwert", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig\n1 - 2 Schaden Tempo 1.50\n(1.00 Schaden pro Sekunde)\nBenutzen: Pömpft einen anderen Schwertträger mit Eurem Schaumstoffschwert. (2 Sek., 500 Ms Abklingzeit)" }
entries[45062] = { ["name"] = "Staubiges Tagebuch", ["text"] = "Questgegenstand\n<Zum Lesen rechtsklicken>" }
entries[45063] = { ["name"] = "Schaumstoffschwertständer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Mit Rechtsklick einen Schaumstoffschwertständer platzieren.\n\nSchaumstoffschwerter verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt. (30 Min Abklingzeit)" }
