entries[45067] = { ["name"] = "Eierkorb", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\nBenutzen: Erhöht das Tempo 10 sec lang um 60%. Funktioniert nur, wo während des Nobelgartenfestes bunt gefärbte Eier versteckt sind. (10 Sek. Abklingzeit)" }
entries[45070] = { ["name"] = "Kristall des Sehers", ["text"] = "Questgegenstand\nBenutzen: Enthüllt die Wahrheit über eine Leiche in einem nahen Grab. Der Kristall des Sehers kann nur in der Nähe von Sir Wendells Grab, Loriens Grab und Conalls Grab verwendet werden." }
