entries[45080] = { ["name"] = "Großer Oberschenkelknochen", ["text"] = "Questgegenstand\nBenutzen: Zieht Maloric eins über, damit er bewusstlos wird und Ihr ihn durchsuchen könnt. Kann nur genutzt werden, wenn Ihr hinter Maloric steht. (5 Sek. Abklingzeit)" }
