entries[45083] = { ["name"] = "Verzaubertes Zaumzeug", ["text"] = "Questgegenstand\nBenutzen: Übernimmt die Kontrolle über den Greifen des Schwarzen Ritters und zwingt ihn, Euch zu zeigen, wo der Schwarze Ritter trainiert und sich auf das Turnier vorbereitet hat. (5 Sek. Abklingzeit)" }
entries[45084] = { ["name"] = "Buch der Handwerksgeheimnisse", ["text"] = "Accountgebunden\nBenötigt Stufe 1 - 80 ( 80)\nBenötigt Schneiderei (1)\nWenn Ihr einen Punkt im Schneidern erhaltet, gewinnt Ihr das Zweifache des normalen Betrags." }
