entries[46026] = { ["name"] = "Rolle der Waffenverzauberung - Klingenbarrikade", ["text"] = "Benutzen: Eine Waffe dauerhaft so verzaubern, dass sie gelegentlich bei einem erzielten Treffer den Effekt 'Klingenbarrikade' gewährt. Die Klingenbarrikade erhöht Eure Parierwertung um 200 und verursacht bei Eurem nächsten Parieren 600 bis 800 Schaden. Hält 10 Sek. lang an.\n\nUm diese Verzauberung nutzen zu können, muss der Träger mindestens Stufe 75 erreicht haben." }
entries[46027] = { ["name"] = "Formel: Waffe - Klingenbarrikade", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (450)\nBenutzen: Lehrt Euch, eine Waffe dauerhaft zu verzaubern, sodass gelegentlich Klingenbarrikade ausgelöst wird, wenn Ihr einen Feind schlagt. Dadurch wird die Parierwertung erhöht und bei Eurem nächsten Parieren Schaden verursacht. Verzauberung benötigt Stufe 75\nEine Waffe dauerhaft so verzaubern, dass sie gelegentlich bei einem erzielten Treffer den Effekt 'Klingenbarrikade' gewährt. Die Klingenbarrikade erhöht Eure Parierwertung um 200 und verursacht bei Eurem nächsten Parieren 600 bis 800 Schaden. Hält 10 Sek. lang an.\n\nUm diese Verzauberung nutzen zu können, muss der Träger mindestens Stufe 75 erreicht haben." }
