entries[46098] = { ["name"] = "Rolle der Waffenverzauberung - Blutsauger", ["text"] = "Benutzen: Eine Waffe dauerhaft so verzaubern, dass sie gelegentlich bei einem erzielten Treffer oder dem Verursachen von Blutungseffekten den Effekt 'Blutreserve' gewährt. Wenn Eure Gesundheit unter 35% sinkt, stellt die Blutreserve 360 to 440 Gesundheit wieder her. Hält 20 sec lang an und ist 5-mal stapelbar.\n\nUm diese Verzauberung nutzen zu können, muss der Träger mindestens Stufe 75 erreicht haben." }
