entries[46108] = { ["name"] = "Technik: Rituale des Neumonds", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Inschriftenkunde (350)\nBenutzen: Lehrt Euch wie man Rituale des Neumonds schreibt.\nRituale des Neumonds\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+37 Ausdauer\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 36.\nAnlegen: Erhöht die Trefferwertung um 25.\nBenutzen: Verwandelt Euch in einen riesigen Wolf. (10 Min Abklingzeit)\nBenötigt Meerestinte (5), Widerstandsfähiges Pergament (10), Äonenschatten (3)" }
entries[46109] = { ["name"] = "Meeresschildkröte", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt Reiten (75)\nBenutzen: Lehrt Euch, wie man eine Meeresschildkröte beschwört. Dieses Reittier ist an Land nicht besonders flink, aber ein großartiger Schwimmer.\nBeschwört eine reitbare Meeresschildkröte und gibt sie wieder frei. Dieses Reittier ist an Land nicht besonders flink, aber ein großartiger Schwimmer.\n\nDurch ihre ausdauernde und zähe Natur wird ihr Schwimmtempo durch Effekte, die das Reittiertempo verringern oder erhöhen, nicht verändert." }
